-- Generated by `npm run data:build-country-info` from data/curated/country_info.csv.
-- Do not edit by hand: edit the CSV and re-run the script.
-- Run after migration_012_country_info.sql. Safe to run more than once.
-- 27 countries; post-study 16, proof of funds 7, work hours 16 filled in.
on conflict (country) do update set
  post_study_text = excluded.post_study_text,
  post_study_months = excluded.post_study_months,
  post_study_source_url = excluded.post_study_source_url,
  post_study_checked_on = excluded.post_study_checked_on,
  funds_text = excluded.funds_text,
  funds_amount = excluded.funds_amount,
  funds_currency = excluded.funds_currency,
  funds_period = excluded.funds_period,
  funds_source_url = excluded.funds_source_url,
  funds_checked_on = excluded.funds_checked_on,
  work_text = excluded.work_text,
  work_hours_per_week = excluded.work_hours_per_week,
  work_source_url = excluded.work_source_url,
  work_checked_on = excluded.work_checked_on,
  notes = excluded.notes,
  updated_at = now();
