insert into public.country_info (country, post_study_text, post_study_months, post_study_source_url, post_study_checked_on, funds_text, funds_amount, funds_currency, funds_period, funds_source_url, funds_checked_on, work_text, work_hours_per_week, work_source_url, work_checked_on, notes)
values
  ('Australia', 'Temporary Graduate visa (Post-Higher Education Work stream): 2 years after a bachelor''s degree (3 years after a research master''s or PhD)', 24, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/temporary-graduate-485/post-higher-education-work', '2026-10-06'::date, 'AUD 29,710 for 12 months of living costs, plus the first year''s course fees and travel', 29710, 'AUD', 'year', 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500', '2026-10-06'::date, 'Up to 48 hours a fortnight while the course is in session', 24, 'https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500', '2026-10-06'::date, 'Work limit is set per fortnight (48 hours); shown here as 24 a week'),
  ('Austria', 'A one-time 12-month renewal of the student residence permit to look for work or start a business', 12, 'https://www.migration.gv.at/en/living-and-working-in-austria/study-in-austria/', '2026-10-06'::date, null, null, null, null, null, null, 'Up to 20 hours a week (the employer applies for a work permit, without a labour market test)', 20, 'https://www.migration.gv.at/en/living-and-working-in-austria/study-in-austria/', '2026-10-06'::date, 'Proof of funds: not on the page checked'),
  ('Belgium', null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Not checked yet: fill in by hand from the government immigration website'),
  ('Canada', 'Post-graduation work permit: up to 3 years after a programme of 2 years or more; a shorter programme (at least 8 months) gives up to the programme''s length', 36, 'https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/after-graduation/about.html', '2026-10-06'::date, 'CA$23,448 a year for one person outside Quebec (applications from 1 September 2026), not counting tuition and travel', 23448, 'CAD', 'year', 'https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html', '2026-10-06'::date, 'Up to 24 hours a week off campus during term; unlimited hours during scheduled breaks', 24, 'https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html', '2026-10-06'::date, 'Quebec sets its own proof-of-funds amount'),
  ('China', null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Not checked yet: fill in by hand from the government immigration website'),
  ('Denmark', 'Job-seeking permit after a bachelor''s or master''s: 1 year under the rules from 1 October 2026 (3 years under the earlier rules, and after a PhD)', 12, 'https://nyidanmark.dk/pl-PL/You-want-to-apply/Study/Study---job-seeking/Study---3-years-job-seeking', '2026-10-06'::date, null, null, null, null, null, null, 'Up to 90 hours a month from September to May; full-time in June, July and August', null, 'https://nyidanmark.dk/pl-PL/You-want-to-apply/Study/Study---job-seeking/Study---3-years-job-seeking', '2026-10-06'::date, 'Work limit is set per month (90 hours), so no weekly figure is stored. Proof of funds: not checked yet'),
  ('Finland', null, null, null, null, '€800 a month; €9,600 in the bank for studies of a year or longer', 800, 'EUR', 'month', 'https://migri.fi/en/income-requirement-for-students', '2026-10-06'::date, 'An average of 30 hours a week over the year', 30, 'https://migri.fi/en/working-and-internships-during-studies', '2026-10-06'::date, 'Post-study: a permit to look for work exists, but its length wasn''t stated on the pages checked; fill in by hand'),
  ('France', 'Job seeker / business creator residence permit: 12 months, not renewable, for master''s-level graduates (or a licence professionnelle); an ordinary bachelor''s (licence) doesn''t qualify', 12, 'https://www.campusfrance.org/en/job-seeker-business-creator-residence-permit', '2026-10-06'::date, null, null, null, null, null, null, 'Up to 964 hours a year (60% of full-time work)', null, 'https://www.campusfrance.org/en/working-student', '2026-10-06'::date, 'Campus France is the French government agency for international students. Proof of funds: not checked yet'),
  ('Germany', 'Up to 18 months after graduating to look for a job, with permission to take up any work meanwhile', 18, 'https://www.bamf.de/EN/Themen/MigrationAufenthalt/ZuwandererDrittstaaten/Bildung/Studium/studium-node.html', '2026-10-06'::date, null, null, null, null, null, null, null, null, null, null, 'Proof of funds and work limits are left empty on purpose: the official pages checked disagree (the Federal Foreign Office FAQ says 120 full or 240 half days a year; a German mission page still shows an older blocked-account amount). Check the German mission in your country'),
  ('Hong Kong', 'Immigration Arrangements for Non-local Graduates (IANG): 24 months'' stay with no other conditions, so you may take any job', 24, 'https://www.immd.gov.hk/eng/services/visas/IANG.html', '2026-10-06'::date, null, null, null, null, null, null, 'Part-time on-campus work up to 20 hours a week; off-campus work only in the summer (1 June to 31 August)', 20, 'https://www.immd.gov.hk/eng/services/visas/study.html', '2026-10-06'::date, 'Proof of funds: not checked yet'),
  ('India', null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'Not checked yet: fill in by hand from the government immigration website'),
  ('Ireland', 'Third Level Graduate Programme (Stamp 1G): 12 months after a level 8 (honours bachelor''s) award', 12, 'https://www.irishimmigration.ie/my-situation-has-changed-since-i-arrived-in-ireland/third-level-graduate-programme/', '2026-10-06'::date, null, null, null, null, null, null, 'Up to 20 hours a week in term time; up to 40 hours a week in June to September and 15 December to 15 January', 20, 'https://www.irishimmigration.ie/coming-to-study-in-ireland/frequently-asked-questions-for-students/', '2026-10-06'::date, 'Proof of funds: no amount found on the immigration service''s pages; fill in by hand'),
  ('Italy', 'Up to 12 months on a job-seeking permit after a laurea (bachelor''s or master''s), a doctorate or a university master in Italy', 12, 'https://integrazionemigranti.gov.it/it-it/Ricerca-news/Dettaglio-news/id/1929/Si-puo-convertire-un-permesso-di-soggiorno-per-studio-in-un-permesso-per-lavoro-', '2026-10-06'::date, null, null, null, null, null, null, null, null, null, null, 'Source is the Italian government''s integration portal (in Italian). Proof of funds and work limits: not checked yet'),
