  ('New Zealand', 'Post-Study Work Visa: up to 3 years, depending on the qualification and how long you studied', 36, 'https://www.immigration.govt.nz/visas/post-study-work-visa/', '2026-10-06'::date, 'NZD 20,000 for each year of tertiary study', 20000, 'NZD', 'year', 'https://www.immigration.govt.nz/visas/fee-paying-student-visa/', '2026-10-06'::date, 'Up to 25 hours a week while studying and full-time in holidays, depending on your visa conditions', 25, 'https://www.immigration.govt.nz/visas/fee-paying-student-visa/', '2026-10-06'::date, null),
