  ('Spain', 'Residence permit to look for work or start a business: 24 months, not extendable, after a university degree. You may not work on this permit until you get a work authorisation', 24, 'https://www.inclusion.gob.es/en/web/migraciones/w/20.-autorizacion-de-residencia-para-busqueda-de-empleo-o-inicio-de-proyecto-empresarial', '2026-10-06'::date, null, null, null, null, null, null, 'Work must be compatible with studies and not exceed 30 hours (the official sheet doesn''t say per what period)', null, 'https://www.inclusion.gob.es/en/web/migraciones/w/hoja-4-bis-acceso-al-empleo-de-las-personas-titulares-de-una-autorizacion-de-estancia-de-larga-duracion-por-estudios-movilidad-de-alumnos-servicios-de-voluntariado-o-actividades-formativas', '2026-10-06'::date, 'Proof of funds: not checked yet'),
  ('Sweden', 'Residence permit to look for work or start a business: up to 1 year after bachelor''s or master''s studies', 12, 'https://www.migrationsverket.se/en/you-want-to-extend/study/look-for-work-after-completing-your-studies-in-sweden.html', '2026-10-06'::date, 'SEK 10,656 a month (applications in 2026)', 10656, 'SEK', 'month', 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html', '2026-10-06'::date, 'Up to 15 hours a week (permits granted on or after 11 June 2026)', 15, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html', '2026-10-06'::date, null),
  ('Switzerland', '6 months after finishing studies to look for a job that matches the qualification', 6, 'https://www.sem.admin.ch/sem/en/home/themen/arbeit/faq.html', '2026-10-06'::date, null, null, null, null, null, null, 'Up to 15 hours a week outside the holidays, starting no sooner than 6 months after the course begins', 15, 'https://www.sem.admin.ch/sem/en/home/themen/arbeit/faq.html', '2026-10-06'::date, 'Proof of funds is set by each canton; not filled in'),
