  ('United Kingdom', 'Graduate visa: 18 months if you apply on or after 1 January 2027 (2 years if you apply by 31 December 2026; 3 years after a PhD)', 18, 'https://www.gov.uk/graduate-visa', '2026-10-06'::date, '£1,171 a month for up to 9 months for courses outside London (£1,529 a month in London), on top of course fees not yet paid', 1171, 'GBP', 'month', 'https://www.gov.uk/student-visa/money', '2026-10-06'::date, 'Degree-level students: 20 hours a week in term time, full-time outside term time', 20, 'https://www.gov.uk/guidance/immigration-rules/immigration-rules-appendix-student', '2026-10-06'::date, null),
  ('United States', 'Up to 12 months of Optional Practical Training (OPT) after completing studies, plus a 24-month extension for eligible STEM degrees', 12, 'https://www.uscis.gov/working-in-the-united-states/students-and-exchange-visitors/optional-practical-training-opt-for-f-1-students', '2026-10-06'::date, null, null, null, null, null, null, 'On-campus work: no more than 20 hours a week while school is in session', 20, 'https://studyinthestates.dhs.gov/students/work/working-in-the-united-states', '2026-10-06'::date, 'Proof of funds: there is no single government amount; each school states the cost of attendance on the Form I-20')
